#include <map>
#include <string>
#include <iostream>

int main() {
    std::map<int, std::string> coll;
    coll[77] = "hello"; // Insertion and assignment

    // Lookup for existing key (no insertion)
    std::cout << "77: " << coll[77] << std::endl;

    // Lookup for non-existent key (Auto-insertion occurs)
    std::cout << "42: " << coll[42] << std::endl; 

    // coll now has size 2. Key 42 exists with value "".
    std::cout << "Map size: " << coll.size() << std::endl;
}
